// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

library StorageSlot {
    struct AddressSlot {
        address value;
    }

    struct Uint256Slot {
        uint256 value;
    }

    function getAddressSlot(bytes32 slot) internal pure returns (AddressSlot storage r) {
        assembly {
            r.slot := slot
        }
    }

    function getUint256Slot(bytes32 slot) internal pure returns (Uint256Slot storage r) {
        assembly {
            r.slot := slot
        }
    }
}

contract EIP1967Proxy {
    bytes32 internal constant _IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    bytes32 internal constant _ADMIN_SLOT = 0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    function _setAdmin(address admin_) internal {
        StorageSlot.getAddressSlot(_ADMIN_SLOT).value = admin_;
    }

    function _setLogic(address logic_) internal {
        StorageSlot.getAddressSlot(_IMPLEMENTATION_SLOT).value = logic_;
    }

    function logic() public view returns (address) {
        return StorageSlot.getAddressSlot(_IMPLEMENTATION_SLOT).value;
    }

    function admin() public view returns (address) {
       return StorageSlot.getAddressSlot(_ADMIN_SLOT).value;
    }

    fallback () external payable {
        assembly {
            let impl := sload(_IMPLEMENTATION_SLOT)
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    receive () external payable virtual {}
}

contract baseProxy is EIP1967Proxy {
    bytes32 internal constant _PENDING_ADMIN_SLOT = bytes32(uint256(keccak256("rgst.proxy.pendingAdmin")) - 1);
    bytes32 internal constant _ADMIN_UNLOCK_TIME_SLOT = bytes32(uint256(keccak256("rgst.proxy.adminUnlockTime")) - 1);
    bytes32 internal constant _PENDING_LOGIC_SLOT = bytes32(uint256(keccak256("rgst.proxy.pendingLogic")) - 1);
    bytes32 internal constant _PENDING_LOGIC_DATA_HASH_SLOT = bytes32(uint256(keccak256("rgst.proxy.pendingLogicDataHash")) - 1);
    bytes32 internal constant _UPGRADE_UNLOCK_TIME_SLOT = bytes32(uint256(keccak256("rgst.proxy.upgradeUnlockTime")) - 1);

    bytes32 internal constant _DELAY_SLOT = bytes32(uint256(keccak256("rgst.proxy.delay")) - 1);
    bytes32 internal constant _PENDING_DELAY_SLOT = bytes32(uint256(keccak256("rgst.proxy.pendingDelay")) - 1);
    bytes32 internal constant _DELAY_UNLOCK_TIME_SLOT = bytes32(uint256(keccak256("rgst.proxy.delayUnlockTime")) - 1);
    uint256 public constant DEFAULT_PROXY_DELAY = 12 hours;
    uint256 public constant MIN_PROXY_DELAY = 3 hours;
    uint256 public constant MAX_PROXY_DELAY = 7 days;

    event Upgraded(address indexed impl);
    event UpgradeProposed(address indexed newLogic, bytes data, uint256 unlockTime);
    event UpgradeCancelled(address indexed cancelledLogic);
    event AdminChanged(address preAdmin, address newAdmin);
    event AdminChangeStarted(address indexed preAdmin, address indexed newAdmin, uint256 unlockTime);
    event AdminChangeCancelled(address indexed admin, address indexed cancelledAdmin);
    event ProxyDelayChangeStarted(uint256 currentDelay, uint256 newDelay, uint256 unlockTime);
    event ProxyDelayChangeCancelled(uint256 cancelledDelay);
    event ProxyDelayChanged(uint256 previousDelay, uint256 newDelay);

    modifier onlyAdmin(){
        require(msg.sender == admin(), "RGSTProxy: Caller not admin");
        _;
    }

    function pendingAdmin() public view returns (address) {
        return StorageSlot.getAddressSlot(_PENDING_ADMIN_SLOT).value;
    }

    function adminChangeUnlockTime() public view returns (uint256) {
        return StorageSlot.getUint256Slot(_ADMIN_UNLOCK_TIME_SLOT).value;
    }

    function changeAdmin(address newAdmin) external onlyAdmin returns(bool) {
        require(newAdmin != address(0), "RGSTProxy: admin cannot be 0");
        uint256 unlockTime = block.timestamp + proxyDelay();
        StorageSlot.getAddressSlot(_PENDING_ADMIN_SLOT).value = newAdmin;
        StorageSlot.getUint256Slot(_ADMIN_UNLOCK_TIME_SLOT).value = unlockTime;
        emit AdminChangeStarted(admin(), newAdmin, unlockTime);
        return true;
    }

    function cancelAdminChange() external onlyAdmin returns(bool) {
        address pending = pendingAdmin();
        require(pending != address(0), "RGSTProxy: no pending admin");
        _clearPendingAdmin();
        emit AdminChangeCancelled(admin(), pending);
        return true;
    }

    function acceptAdmin() external returns(bool) {
        require(msg.sender == pendingAdmin(), "RGSTProxy: Caller not pending admin");
        require(block.timestamp >= adminChangeUnlockTime(), "RGSTProxy: admin change locked");
        address preAdmin = admin();
        _setAdmin(msg.sender);
        _clearPendingAdmin();
        emit AdminChanged(preAdmin, msg.sender);
        return true;
    }

    function _clearPendingAdmin() internal {
        StorageSlot.getAddressSlot(_PENDING_ADMIN_SLOT).value = address(0);
        StorageSlot.getUint256Slot(_ADMIN_UNLOCK_TIME_SLOT).value = 0;
    }

    function proxyDelay() public view returns (uint256) {
        return StorageSlot.getUint256Slot(_DELAY_SLOT).value;
    }

    function pendingProxyDelay() public view returns (uint256) {
        return StorageSlot.getUint256Slot(_PENDING_DELAY_SLOT).value;
    }

    function proxyDelayUnlockTime() public view returns (uint256) {
        return StorageSlot.getUint256Slot(_DELAY_UNLOCK_TIME_SLOT).value;
    }

    function setProxyDelay(uint256 newDelay) external onlyAdmin returns(bool) {
        require(newDelay >= MIN_PROXY_DELAY && newDelay <= MAX_PROXY_DELAY, "RGSTProxy: delay out of range");
        uint256 unlockTime = block.timestamp + proxyDelay();
        StorageSlot.getUint256Slot(_PENDING_DELAY_SLOT).value = newDelay;
        StorageSlot.getUint256Slot(_DELAY_UNLOCK_TIME_SLOT).value = unlockTime;
        emit ProxyDelayChangeStarted(proxyDelay(), newDelay, unlockTime);
        return true;
    }

    function applyProxyDelay() external onlyAdmin returns(bool) {
        uint256 newDelay = pendingProxyDelay();
        require(newDelay != 0, "RGSTProxy: no pending delay change");
        require(block.timestamp >= proxyDelayUnlockTime(), "RGSTProxy: delay change locked");
        emit ProxyDelayChanged(proxyDelay(), newDelay);
        _setProxyDelay(newDelay);
        _clearPendingProxyDelay();
        return true;
    }

    function cancelProxyDelay() external onlyAdmin returns(bool) {
        uint256 pending = pendingProxyDelay();
        require(pending != 0, "RGSTProxy: no pending delay change");
        _clearPendingProxyDelay();
        emit ProxyDelayChangeCancelled(pending);
        return true;
    }

    function _setProxyDelay(uint256 delay_) internal {
        StorageSlot.getUint256Slot(_DELAY_SLOT).value = delay_;
    }

    function _clearPendingProxyDelay() internal {
        StorageSlot.getUint256Slot(_PENDING_DELAY_SLOT).value = 0;
        StorageSlot.getUint256Slot(_DELAY_UNLOCK_TIME_SLOT).value = 0;
    }

    function pendingLogic() public view returns (address) {
        return StorageSlot.getAddressSlot(_PENDING_LOGIC_SLOT).value;
    }

    function pendingLogicDataHash() public view returns (bytes32) {
        return bytes32(StorageSlot.getUint256Slot(_PENDING_LOGIC_DATA_HASH_SLOT).value);
    }

    function upgradeUnlockTime() public view returns (uint256) {
        return StorageSlot.getUint256Slot(_UPGRADE_UNLOCK_TIME_SLOT).value;
    }

    function proposeUpgrade(address newLogic, bytes calldata data) external onlyAdmin returns(bool) {
        require(newLogic.code.length > 0, "RGSTProxy: logic is not a contract");
        uint256 unlockTime = block.timestamp + proxyDelay();
        StorageSlot.getAddressSlot(_PENDING_LOGIC_SLOT).value = newLogic;
        StorageSlot.getUint256Slot(_PENDING_LOGIC_DATA_HASH_SLOT).value = uint256(keccak256(data));
        StorageSlot.getUint256Slot(_UPGRADE_UNLOCK_TIME_SLOT).value = unlockTime;
        emit UpgradeProposed(newLogic, data, unlockTime);
        return true;
    }

    function cancelUpgrade() external onlyAdmin returns(bool) {
        address pending = pendingLogic();
        require(pending != address(0), "RGSTProxy: no pending upgrade");
        _clearPendingUpgrade();
        emit UpgradeCancelled(pending);
        return true;
    }

    function executeUpgrade(bytes calldata data) external onlyAdmin returns(bool) {
        address newLogic = pendingLogic();
        require(newLogic != address(0), "RGSTProxy: no pending upgrade");
        require(block.timestamp >= upgradeUnlockTime(), "RGSTProxy: upgrade locked");
        require(keccak256(data) == pendingLogicDataHash(), "RGSTProxy: data mismatch");
        _clearPendingUpgrade();
        _setLogic(newLogic);
        emit Upgraded(newLogic);
        if (data.length > 0) {
            (bool success, bytes memory result) = newLogic.delegatecall(data);
            if (!success) {
                assembly {
                    revert(add(result, 32), mload(result))
                }
            }
        }
        return true;
    }

    function _clearPendingUpgrade() internal {
        StorageSlot.getAddressSlot(_PENDING_LOGIC_SLOT).value = address(0);
        StorageSlot.getUint256Slot(_PENDING_LOGIC_DATA_HASH_SLOT).value = 0;
        StorageSlot.getUint256Slot(_UPGRADE_UNLOCK_TIME_SLOT).value = 0;
    }
}

contract RGSTProxy is baseProxy{
    constructor(address impl, string memory name, string memory symbol, uint256 totalSupply, address owner) {
        require(owner != address(0), "RGSTProxy: admin cannot be 0");
        _setAdmin(owner);
        _setLogic(impl);
        _setProxyDelay(DEFAULT_PROXY_DELAY);
        (bool success, bytes memory result) = impl.delegatecall(
            abi.encodeWithSignature("initialize(string,string,uint256,address)", name, symbol, totalSupply, owner)
        );
        if (!success) {
            assembly {
                revert(add(result, 32), mload(result))
            }
        }
    }
}

