interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
}

contract Initialized {
    bool internal initialized;

    modifier noInit(){
        require(!initialized, "initialized");
        _;
        initialized = true;
    }
}

contract Storage is Initialized{
    string  public name;
    string  public symbol;
    uint8   public decimals;

    address public owner;
    address public rebaser;
    address public minter;
    address public receiver;

    uint256 public scalingFactor;
    uint256 internal fragment;
    uint256 internal _totalSupply;
    uint256 constant Decimals = 10**24;
    uint256 constant BASE = 10**18;

    mapping (address => uint256) internal fragmentBalances;
    mapping (address => mapping (address => uint256)) internal allowedFragments;

    address public pendingOwner;

    uint256 public ownershipTransferUnlockTime;

    uint8 public constant ROLE_MINTER = 0;
    uint8 public constant ROLE_REBASER = 1;
    uint8 public constant ROLE_RECEIVER = 2;
    mapping (uint8 => address) public pendingRole;
    mapping (uint8 => uint256) public roleChangeUnlockTime;

    uint256 public constant MAX_REBASE_DELTA = 10**17;
    uint256 public constant MIN_SCALING_FACTOR = 10**12;
    uint256 public lastEpoch;

    uint256 public constant DEFAULT_TIMELOCK_DELAY = 12 hours;
    uint256 public constant MIN_TIMELOCK_DELAY = 3 hours;
    uint256 public constant MAX_TIMELOCK_DELAY = 7 days;
    uint256 public timelockDelay;
    uint256 public pendingTimelockDelay;
    uint256 public timelockDelayUnlockTime;

    modifier onlyRebaser() {
        require(msg.sender == rebaser, "RGST: only rebaser");
        _;
    }

    modifier onlyOwner(){
         require(msg.sender == owner, "RGST: only owner");
        _;
    }

    modifier onlyMinter() {
        require(msg.sender == minter, "RGST: only minter");
        _;
    }
}

interface IRGST is IERC20{
    event Rebase(uint256 epoch, uint256 indexDelta, bool positive);
    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner, uint256 unlockTime);
    event OwnershipTransferCancelled(address indexed owner, address indexed cancelledOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event MinterChanged(address indexed previousMinter, address indexed newMinter);
    event RebaserChanged(address indexed previousRebaser, address indexed newRebaser);
    event ReceiverChanged(address indexed previousReceiver, address indexed newReceiver);
    event RoleChangeStarted(uint8 indexed role, address indexed previousUser, address indexed newUser, uint256 unlockTime);
    event RoleChangeCancelled(uint8 indexed role, address indexed cancelledUser);
    event TimelockDelayChangeStarted(uint256 currentDelay, uint256 newDelay, uint256 unlockTime);
    event TimelockDelayChangeCancelled(uint256 cancelledDelay);
    event TimelockDelayChanged(uint256 previousDelay, uint256 newDelay);

    function mint(uint256 amount) external;
    function mint(address to,uint256 amount) external;

    function burn(uint256 amount) external;
    function rebase(uint256 epoch, uint256 indexDelta, bool positive) external returns (uint256);
    function rebaseByMilli(uint256 epoch, uint256 milli, bool positive) external returns (uint256);

    function rgstToFragment(uint256 value) external view returns (uint256);
    function fragmentToRgst(uint256 value) external view returns (uint256);

    function setMinter(address user) external;
    function setReceiver(address user) external;
    function setRebaser(address user) external;
    function applyRoleChange(uint8 role) external;
    function cancelRoleChange(uint8 role) external;
    function transferOwnership(address newOwner) external;
    function acceptOwnership() external;
    function cancelOwnershipTransfer() external;
    function setTimelockDelay(uint256 newDelay) external;
    function applyTimelockDelay() external;
    function cancelTimelockDelay() external;
}

contract Token is Storage, IERC20{
    using SafeMath for uint256;

    function totalSupply() override external view returns (uint256){
        return _totalSupply;
    }

    function transfer(address to, uint256 value) override external returns (bool) {
        _transferFragment(msg.sender, to, _rgstToFragment(value));
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) override external returns (bool){
        uint256 fragmentValue = _rgstToFragment(value);

        if (allowedFragments[from][msg.sender] != type(uint256).max) {
            allowedFragments[from][msg.sender] = allowedFragments[from][msg.sender].sub(fragmentValue);
        }
        _transferFragment(from, to, fragmentValue);
        emit Transfer(from, to, value);
        return true;
    }

    function balanceOf(address who) override external view returns (uint256){
        return _fragmentToRgst(fragmentBalances[who]);
    }

    function allowance(address owner_, address spender) override external view returns (uint256){
        uint256 allowed = allowedFragments[owner_][spender];
        if (allowed == type(uint256).max) return type(uint256).max;
        return _fragmentToRgst(allowed);
    }

    function approve(address spender, uint256 value) override external returns (bool){
        uint256 fragmentValue = value == type(uint256).max ? type(uint256).max : _rgstToFragment(value);
        allowedFragments[msg.sender][spender] = fragmentValue;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function _mint(address to, uint256 amount) internal {
        require(to != address(0), "to address cannot be 0");
        _totalSupply = _totalSupply.add(amount);
        uint256 scaledAmount = _rgstToFragment(amount);
        fragment = fragment.add(scaledAmount);
        require(scalingFactor <= _maxScalingFactor(), "RGST: max scaling factor too low");
        fragmentBalances[to] = fragmentBalances[to].add(scaledAmount);
        emit Transfer(address(0), to, amount);
    }

    function _burn(address user, uint256 amount) internal {
        require(user != address(0), "user address cannot be 0");
        _totalSupply = _totalSupply.sub(amount);
        uint256 scaledAmount = _rgstToFragment(amount);
        fragment = fragment.sub(scaledAmount);
        fragmentBalances[user] = fragmentBalances[user].sub(scaledAmount);
        emit Transfer(user ,address(0), amount);
    }

    function _transferFragment(address from, address to, uint256 value ) internal {
        require(to != address(0), "to address cannot be 0");
        fragmentBalances[from] = fragmentBalances[from].sub(value);
        fragmentBalances[to] = fragmentBalances[to].add(value);
    }

    function _maxScalingFactor() internal view returns (uint256){
       if (fragment == 0) return type(uint256).max;
       return (type(uint256).max).div(fragment);
    }

    function _fragmentToRgst(uint256 value) internal view returns(uint256){
         return value.mul(scalingFactor).div(Decimals);
    }

    function _rgstToFragment(uint value) internal view returns (uint256){
        return value.mul(Decimals).div(scalingFactor);
    }
}

contract RGST is Token, IRGST{
    using SafeMath for uint256;

    constructor() {
        initialized = true;
    }

    function initialize(string memory name, string memory symbol, uint256 totalSupply, address owner_) external {
        _initialize(name, symbol, 18, totalSupply*10**18, owner_);
    }

    function setReceiver(address user) override external onlyOwner{
        _proposeRole(ROLE_RECEIVER, user);
    }

    function setMinter(address user) override external onlyOwner{
        _proposeRole(ROLE_MINTER, user);
    }

    function setRebaser(address user) override external onlyOwner{
        _proposeRole(ROLE_REBASER, user);
    }

    function applyRoleChange(uint8 role) override external onlyOwner{
        address user = pendingRole[role];
        require(user != address(0), "RGST: no pending role change");
        require(block.timestamp >= roleChangeUnlockTime[role], "RGST: role change locked");
        pendingRole[role] = address(0);
        roleChangeUnlockTime[role] = 0;
        if (role == ROLE_MINTER) {
            emit MinterChanged(minter, user);
            minter = user;
        } else if (role == ROLE_REBASER) {
            emit RebaserChanged(rebaser, user);
            rebaser = user;
        } else {
            emit ReceiverChanged(receiver, user);
            receiver = user;
        }
    }

    function cancelRoleChange(uint8 role) override external onlyOwner{
        address user = pendingRole[role];
        require(user != address(0), "RGST: no pending role change");
        pendingRole[role] = address(0);
        roleChangeUnlockTime[role] = 0;
        emit RoleChangeCancelled(role, user);
    }

    function _proposeRole(uint8 role, address user) internal {
        require(user != address(0), "user address cannot be 0");
        address current = role == ROLE_MINTER ? minter : role == ROLE_REBASER ? rebaser : receiver;
        uint256 unlockTime = block.timestamp + timelockDelay;
        pendingRole[role] = user;
        roleChangeUnlockTime[role] = unlockTime;
        emit RoleChangeStarted(role, current, user, unlockTime);
    }

    function transferOwnership(address newOwner) override external onlyOwner{
        require(newOwner != address(0), "user address cannot be 0");

        pendingOwner = newOwner;
        ownershipTransferUnlockTime = block.timestamp + timelockDelay;
        emit OwnershipTransferStarted(owner, newOwner, ownershipTransferUnlockTime);
    }

    function cancelOwnershipTransfer() override external onlyOwner{
        require(pendingOwner != address(0), "RGST: no pending owner");
        emit OwnershipTransferCancelled(owner, pendingOwner);
        pendingOwner = address(0);
        ownershipTransferUnlockTime = 0;
    }

    function setTimelockDelay(uint256 newDelay) override external onlyOwner{
        require(newDelay >= MIN_TIMELOCK_DELAY && newDelay <= MAX_TIMELOCK_DELAY, "RGST: delay out of range");
        pendingTimelockDelay = newDelay;
        timelockDelayUnlockTime = block.timestamp + timelockDelay;
        emit TimelockDelayChangeStarted(timelockDelay, newDelay, timelockDelayUnlockTime);
    }

    function applyTimelockDelay() override external onlyOwner{
        require(pendingTimelockDelay != 0, "RGST: no pending delay change");
        require(block.timestamp >= timelockDelayUnlockTime, "RGST: delay change locked");
        emit TimelockDelayChanged(timelockDelay, pendingTimelockDelay);
        timelockDelay = pendingTimelockDelay;
        pendingTimelockDelay = 0;
        timelockDelayUnlockTime = 0;
    }

    function cancelTimelockDelay() override external onlyOwner{
        require(pendingTimelockDelay != 0, "RGST: no pending delay change");
        emit TimelockDelayChangeCancelled(pendingTimelockDelay);
        pendingTimelockDelay = 0;
        timelockDelayUnlockTime = 0;
    }

    function acceptOwnership() override external{
        require(msg.sender == pendingOwner, "RGST: only pending owner");
        require(block.timestamp >= ownershipTransferUnlockTime, "RGST: ownership transfer locked");
        emit OwnershipTransferred(owner, msg.sender);
        owner = msg.sender;
        pendingOwner = address(0);
        ownershipTransferUnlockTime = 0;
    }

    function rebaseByMilli(uint256 epoch, uint256 milli, bool positive) override external onlyRebaser returns (uint256){
        require(milli < 1000, "RGST: milli must be less than 1000");
        return _rebase(epoch, milli.mul(BASE).div(1000), positive);

    }

    function rebase(uint256 epoch, uint256 indexDelta, bool positive) override external onlyRebaser returns (uint256){
         return _rebase(epoch, indexDelta, positive);
    }

    function mint(uint256 amount) override external onlyMinter {
        _mint(receiver, amount);
    }

    function mint( address _to , uint256 _amount) override external onlyMinter {
        _mint(_to, _amount);
    }

    function burn(uint256 amount) override external {
        _burn(msg.sender, amount);
    }

    function fragmentToRgst(uint256 value) override external view returns (uint256){
        return _fragmentToRgst(value);
    }

    function rgstToFragment(uint256 value) override external view returns (uint256){
      return _rgstToFragment(value);
    }

    function _rebase(uint256 epoch, uint256 indexDelta, bool positive) internal returns (uint256){
        require(epoch > lastEpoch, "RGST: epoch must increase");
        require(indexDelta <= MAX_REBASE_DELTA, "RGST: rebase too large");
        lastEpoch = epoch;
        emit Rebase(epoch, indexDelta, positive);
        if (indexDelta == 0)  return _totalSupply;

        if (!positive) {
            uint256 newScalingFactor = scalingFactor.mul(BASE.sub(indexDelta)).div(BASE);
            require(newScalingFactor >= MIN_SCALING_FACTOR, "RGST: scaling factor too low");
            scalingFactor = newScalingFactor;
        } else {
            uint256 newScalingFactor = scalingFactor.mul(BASE.add(indexDelta)).div(BASE);
            if (newScalingFactor < _maxScalingFactor()) {
                scalingFactor = newScalingFactor;
            } else {
                scalingFactor = _maxScalingFactor();
            }
        }

        _totalSupply = _fragmentToRgst(fragment);
        return _totalSupply;
    }

    function _initialize(string memory _name, string memory _symbol, uint8 _decimals, uint256 _initTotalSupply, address _owner) internal noInit {
        require(_owner != address(0), "user address cannot be 0");
        scalingFactor = BASE;
        owner = _owner;
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        _totalSupply = _initTotalSupply;
        fragment = _rgstToFragment(_initTotalSupply);
        fragmentBalances[_owner] = fragment;
        rebaser = _owner;
        minter = _owner;
        receiver = _owner;
        timelockDelay = DEFAULT_TIMELOCK_DELAY;
        emit OwnershipTransferred(address(0), _owner);
        emit Transfer(address(0), _owner, _initTotalSupply);
    }

    function version() external pure returns (string memory) {
        return "v1.0.0";
    }
}
